import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseDataViewExposes, UseDataViewProps, UseDataViewState } from '@primereact/types/headless/dataview';
/**
 * Defines passthrough(pt) options type in DataViewRoot component.
 */
export type DataViewRootPassThroughType<E> = PassThroughType<DataViewRootInstance, E>;
/**
 * Defines passthrough(pt) options of DataViewRoot component.
 */
export interface DataViewRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataViewRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DataViewRoot component.
 */
export interface DataViewRootProps extends BaseComponentProps<DataViewRootInstance, UseDataViewProps, DataViewRootPassThrough> {
}
/**
 * Defines valid state in DataViewRoot component.
 * @extends UseDataViewState
 */
export interface DataViewRootState extends UseDataViewState {
}
/**
 * Defines the methods and properties exposed by DataViewRoot component.
 * @extends UseDataViewExposes
 */
export interface DataViewRootExposes extends UseDataViewExposes {
}
/**
 * Instance of DataViewRoot component.
 */
export type DataViewRootInstance = ComponentInstance<DataViewRootProps, DataViewRootState, DataViewRootExposes>;
